                stBtn.innerHTML = `${stKey ? `<code class="db-issue-key-chip">${esc(stKey)}</code>` : ''}<span>${esc(st.title || 'Untitled subtask')}</span>`;
                stBtn.onclick = () => ArchitectDatabase.openDatabaseRow(st, qb);
