    xInp.oninput = () => { cropX = Math.min(100, Math.max(0, Number(xInp.value) || 0)); layoutCropFrame(); };
    yInp.oninput = () => { cropY = Math.min(100, Math.max(0, Number(yInp.value) || 0)); layoutCropFrame(); };
