                cur.imageAssetId = asset.id;
                cur.imageUrl = url;
                cur.imageCropX = 50;
                cur.imageCropY = 50;
                cur.imageCropZoom = 100;
                cur.imageCropAspect = getFormButtonCropAspect(b.id, cur).aspect;
                commit(true);
                openBtnCropModal(url, asset.id);
