function toggleCommentsDrawer(forceOpen = null) {
    const drawer = $('#comments-drawer');
    const btn = $('[data-action="toggle-comments"]');
    if (!drawer)
        return;
    const nextOpen = forceOpen === null ? drawer.hidden : !!forceOpen;
    if (nextOpen) {
        const assetsSidebar = $('#assets-sidebar');
        if (assetsSidebar && !assetsSidebar.hidden)
            toggleAssetsSidebar(false);
        const fds = $('#form-design-sidebar');
        if (fds && !fds.hidden)
            toggleFormDesignSidebar(false);
        const curThreads = ensurePageComments(current());
        if (forceOpen === null && curThreads.length > 0 && curThreads.every(t => !!t.resolved) && commentsFilter === 'open') {
            commentsFilter = 'resolved';
        }
    }
    drawer.hidden = !nextOpen;
    btn?.setAttribute('aria-expanded', String(nextOpen));
    if (nextOpen)
        renderCommentsDrawer();
    layoutRightComments(current());
    if (commentPopoverState)
        renderCommentPopover();
}
