$('#import-notion-folder')?.addEventListener('change', async (e) => {
    const inp = e.target;
    const files = Array.from(inp.files || []);
    inp.value = '';
    if (!files.length)
        return;
    const feedbackEl = $('#notion-import-feedback');
    try {
        if (feedbackEl)
            feedbackEl.textContent = `Reading ${files.length} files from Notion export folder…`;
        const filesMap = new Map();
        let bundleFile = null;
        for (const f of files) {
            const rel = (f.webkitRelativePath || f.name).replace(/\\/g, '/');
            filesMap.set(rel, f);
            const lower = rel.toLowerCase();
            if (lower.endsWith('/normalized/bundle.json') || lower === 'normalized/bundle.json') {
                bundleFile = f;
            }
            else if (!bundleFile && (lower === 'bundle.json' || lower.endsWith('/bundle.json'))) {
                bundleFile = f;
            }
        }
        if (!bundleFile)
            throw new Error('Could not find normalized/bundle.json inside the selected folder.');
        const bundle = JSON.parse(await bundleFile.text());
        const replaceEl = $('#import-notion-replace');
        const stats = await importNotionBundle(bundle, filesMap, { replaceExisting: replaceEl ? replaceEl.checked : true });
        const msg = `Imported ${stats.importedPages} pages, ${stats.newUsers} collaborator profiles, ${stats.commentMessages} comments, and ${stats.ingestedAssets} assets (${stats.reusedDuplicates} duplicates skipped).`;
        if (feedbackEl)
            feedbackEl.textContent = msg;
        toast(`Notion folder imported (${stats.importedPages} pages)`);
    }
    catch (err) {
        if (feedbackEl)
            feedbackEl.textContent = err?.message || 'Could not import Notion folder.';
    }
});
